from collections import deque
q=deque()
for j in range(H):
    for k in range(W):
        if I[j,k]==6:
            D[j][k]=0; q.append((j,k))
while q:
    a,b=q.popleft()
    for dj in(-1,0,1):
        for dk in(-1,0,1):
            x,y=a+dj,b+dk
            if 0<=x<H and 0<=y<W and not seen[x][y] and (x+y>=0) and (a+b>=0):
                seen[x][y]=True
                D[x][y]=D[a][b]+1
                q.append((x,y))
